function sendPromptToActiveSession(promptText) {
  try {
    haptic('tap')
    // Find composer input in Hermes Desktop DOM
    const editor = document.querySelector('[data-slot="composer-rich-input"]')
    if (editor) {
      editor.focus()
      document.execCommand('selectAll', false, null)
      document.execCommand('insertText', false, promptText)
      
      const enterEvent = new KeyboardEvent('keydown', {
        key: 'Enter',
        code: 'Enter',
        keyCode: 13,
        which: 13,
        bubbles: true,
        cancelable: true
      })
      editor.dispatchEvent(enterEvent)
    } else {
      host.notify({ kind: 'info', message: `Perintah: ${promptText}` })
    }
  } catch (err) {
    host.notify({ kind: 'error', message: String(err) })
  }
}

