function LexaSimpleWelcome() {
  const services = [
    ['01 / INFRASTRUCTURE', 'Infrastruktur', 'MikroTik, Proxmox VE, VPS, hosting, dan network operation.', 'Lexa bantu urusan infrastructure Hosterbyte'],
    ['02 / HOSTING', 'Server & Hosting', 'cPanel, DirectAdmin, CloudLinux, WHMCS, dan monitoring.', 'Lexa bantu urusan server dan hosting Hosterbyte'],
    ['03 / DEVELOPMENT', 'Development', 'Laravel, PHP, WordPress, API integration, dan automation.', 'Lexa bantu development atau system automation Hosterbyte'],
    ['04 / OPERATIONS', 'Security & Ops', 'Audit, backup, troubleshooting, deployment, dan dokumentasi.', 'Lexa lakukan security audit dan operational review Hosterbyte']
  ]
  const avatar = `<img src="${'data:image/jpeg;base64,'}" alt="Lexa — Personal AI Assistant" class="lexa-avatar-photo" />`
  return jsx('div', { className: 'lexa-simple', children: [
    jsxs('section', { className: 'lexa-simple-hero', children: [
      jsx('div', { className: 'lexa-simple-avatar', dangerouslySetInnerHTML: { __html: avatar } }),
      jsx('p', { className: 'lexa-simple-kicker', children: 'HOSTERBYTE // TECHNICAL OPERATOR' }),
      jsx('h1', { children: 'LEXA' }),
      jsx('p', { className: 'lexa-simple-subtitle', children: 'PERSONAL AI ASSISTANT // HOSTERBYTE' })
    ] }),
    jsx('p', { className: 'lexa-simple-description', children: 'Lexa membantu mengelola infrastruktur IT, server, jaringan, development, dan automasi operasional Hosterbyte — secara terarah, aman, dan terverifikasi.' }),
    jsx('section', { className: 'lexa-simple-services', children: services.map(([label, title, desc, prompt]) => jsxs('button', { type: 'button', className: 'lexa-simple-service', onClick: () => sendPromptToActiveSession(prompt), children: [jsx('small', { children: label }), jsx('h2', { children: title }), jsx('p', { children: desc })] })) }),
    jsxs('footer', { className: 'lexa-simple-footer', children: [jsx('span', { children: 'LEXA / HOSTERBYTE' }), jsx('span', { className: 'lexa-simple-ready', children: '● READY TO ASSIST' })] })
  ] })
}

